/* ─────────────────────────────────────────────────────────
 * PHONE FIELD: the country code and the number, as one field.
 *
 *   [🇮🇳 +91 ⌄ | 98765 43210]
 *
 * The code opens a searchable list. It is origin-aware: the list grows
 * out of the code button that opened it (transform-origin follows Base UI's
 * --transform-origin), never from its own centre.
 *
 *   open    scale 0.95 → 1 + fade, 150ms ease-out (0.23, 1, 0.32, 1)
 *   close   scale 1 → 0.95 + fade, 100ms (exits faster than entrances)
 *   reduced motion: the fade only
 *
 * Picking a country puts focus in the number. Flags are emoji (no image
 * files); systems without flag emoji show the two-letter code instead.
 * ───────────────────────────────────────────────────────── */

/** A country the code list offers. */
export interface PhoneCountry {
  /** ISO 3166 two-letter code, e.g. "IN". Also gives the flag and name. */
  code: string;
  /** International dialling code, e.g. "+91". */
  dial: string;
}

export const DEFAULT_PHONE_COUNTRIES: PhoneCountry[] = [
  { code: "US", dial: "+1" },
  { code: "CA", dial: "+1" },
  { code: "GB", dial: "+44" },
  { code: "IN", dial: "+91" },
  { code: "AU", dial: "+61" },
  { code: "NZ", dial: "+64" },
  { code: "IE", dial: "+353" },
  { code: "DE", dial: "+49" },
  { code: "FR", dial: "+33" },
  { code: "ES", dial: "+34" },
  { code: "IT", dial: "+39" },
  { code: "NL", dial: "+31" },
  { code: "BE", dial: "+32" },
  { code: "CH", dial: "+41" },
  { code: "AT", dial: "+43" },
  { code: "SE", dial: "+46" },
  { code: "NO", dial: "+47" },
  { code: "DK", dial: "+45" },
  { code: "FI", dial: "+358" },
  { code: "PT", dial: "+351" },
  { code: "PL", dial: "+48" },
  { code: "TR", dial: "+90" },
  { code: "IL", dial: "+972" },
  { code: "AE", dial: "+971" },
  { code: "SA", dial: "+966" },
  { code: "EG", dial: "+20" },
  { code: "NG", dial: "+234" },
  { code: "KE", dial: "+254" },
  { code: "ZA", dial: "+27" },
  { code: "BR", dial: "+55" },
  { code: "MX", dial: "+52" },
  { code: "AR", dial: "+54" },
  { code: "JP", dial: "+81" },
  { code: "KR", dial: "+82" },
  { code: "CN", dial: "+86" },
  { code: "HK", dial: "+852" },
  { code: "SG", dial: "+65" },
  { code: "MY", dial: "+60" },
  { code: "ID", dial: "+62" },
  { code: "PH", dial: "+63" },
  { code: "TH", dial: "+66" },
  { code: "VN", dial: "+84" },
  { code: "PK", dial: "+92" },
  { code: "BD", dial: "+880" },
];

// Country names through Intl ("India", "United Kingdom"), not a table.
const REGION_NAMES = new Intl.DisplayNames(["en"], { type: "region" });
const nameOf = (code: string) => REGION_NAMES.of(code) ?? code;

// The flag emoji for a two-letter code: each letter as a regional indicator.
// "A" (65) maps to U+1F1E6 (127462), REGIONAL INDICATOR SYMBOL LETTER A.
const REGIONAL_A = 127_462;
const flagOf = (code: string) =>
  String.fromCodePoint(
    ...[...code.toUpperCase()].map(
      (letter) => REGIONAL_A + (letter.codePointAt(0) ?? 65) - 65
    )
  );

// Origin-aware entrance and exit (see the header). The shadow is the
// block's float, so the list matches its other menus. The reduced-motion
// overrides carry the same data-open/closed as shadcn's zoom and slide, so
// they're as specific and win.
const LIST_MOTION =
  "origin-(--transform-origin) ease-[cubic-bezier(0.23,1,0.32,1)] data-open:duration-150 data-closed:duration-100 motion-reduce:data-open:[--tw-enter-scale:1] motion-reduce:data-closed:[--tw-exit-scale:1] motion-reduce:data-open:[--tw-enter-translate-y:0] motion-reduce:data-closed:[--tw-exit-translate-y:0]";

export const PhoneField = ({
  countries,
  country,
  describedBy,
  id,
  invalid,
  number,
  onCountryChange,
  onNumberChange,
}: {
  countries: PhoneCountry[];
  country: string;
  describedBy?: string;
  id: string;
  invalid?: boolean;
  number: string;
  onCountryChange: (code: string) => void;
  onNumberChange: (value: string) => void;
}) => {
  const [open, setOpen] = useState(false);
  const numberRef = useRef<HTMLInputElement>(null);
  const current =
    countries.find((item) => item.code === country) ?? countries[0];

  return (
    <div
      className={cn(
        RING,
        "dark:bg-input/30 focus-within:border-ring focus-within:ring-ring/50 flex h-9 items-center rounded-md bg-transparent transition-[color,box-shadow] focus-within:ring-[3px]",
        invalid && "border-destructive"
      )}
    >
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger
          render={
            <button
              type="button"
              aria-label={`Country code: ${nameOf(current.code)} (${current.dial})`}
              // No divider: a light tint marks the country code as its own button.
              className="bg-muted/60 hover:bg-accent focus-visible:bg-accent flex h-full shrink-0 items-center gap-1.5 rounded-l-[calc(var(--radius-md)-1px)] pr-2 pl-3 text-sm outline-none"
            />
          }
        >
          <span aria-hidden className="text-base leading-none">
            {flagOf(current.code)}
          </span>
          <span className="tabular-nums">{current.dial}</span>
          <HugeiconsIcon
            icon={ArrowDown01Icon}
            strokeWidth={1.75}
            className="text-muted-foreground size-3.5"
          />
        </PopoverTrigger>
        <PopoverContent
          align="start"
          sideOffset={6}
          // Overrides: no padding (the list fills it), the block's float
          // shadow, and the origin-aware motion above.
          className={cn(
            FLOAT,
            LIST_MOTION,
            "w-64 overflow-hidden rounded-lg p-0"
          )}
        >
          {/* Override: no rule under the search field; space separates it. */}
          <Command className="[&_[data-slot=command-input-wrapper]]:border-b-0">
            <CommandInput placeholder="Search country or code" />
            <CommandList className="max-h-72 overscroll-contain">
              <CommandEmpty>No country found.</CommandEmpty>
              <CommandGroup>
                {countries.map((item) => (
                  <CommandItem
                    key={item.code}
                    value={`${nameOf(item.code)} ${item.dial} ${item.code}`}
                    onSelect={() => {
                      onCountryChange(item.code);
                      setOpen(false);
                      // The number is what comes next.
                      requestAnimationFrame(() => numberRef.current?.focus());
                    }}
                  >
                    <span aria-hidden className="text-base leading-none">
                      {flagOf(item.code)}
                    </span>
                    <span className="min-w-0 flex-1 truncate">
                      {nameOf(item.code)}
                    </span>
                    <span className="text-muted-foreground text-xs tabular-nums">
                      {item.dial}
                    </span>
                    <HugeiconsIcon
                      icon={Tick02Icon}
                      strokeWidth={2}
                      className={cn(
                        "size-4",
                        item.code === current.code ? "opacity-100" : "opacity-0"
                      )}
                    />
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
      <Input
        ref={numberRef}
        id={id}
        type="tel"
        inputMode="tel"
        autoComplete="tel-national"
        placeholder="98765 43210"
        value={number}
        aria-invalid={invalid}
        aria-describedby={describedBy}
        onChange={(event) => onNumberChange(event.target.value)}
        // Override: the box around it draws the ring and focus.
        className="h-full min-w-0 flex-1 border-0 bg-transparent pl-2.5 shadow-none focus-visible:ring-0 dark:bg-transparent"
      />
    </div>
  );
};

/* ─────────────────────────────────────────────────────────
 * SURFACES: shadows for elevation, not borders.
 *
 *   lift    surfaces: soft depth only, no ring (light); card colour (dark)
 *   ring    form fields only: a faint 1px ring so a field can be found
 *   float   a deeper lift, for anything that hovers
 *   photo   an inset ring and a soft inner shadow, so the photo's edge
 *           reads crisply on any page colour (pure black / white, never
 *           a tint, which would fringe the image)
 *
 * Every ring keeps a transparent 1px border underneath: forced-colors
 * mode drops box-shadow and paints that border instead, and the box stays
 * the size the border gave it. Error and focus borders still colour it.
 * No dividers anywhere: lists are stacks of ringed cards (CARD), sections
 * are split by space, the app's sidebar and top bar by a tint (the page
 * sits on muted, the chrome on background). Every edge is a shadow or a
 * change of colour, never a rule.
 * ───────────────────────────────────────────────────────── */

// Surfaces (cards, panels, frames): depth only, NO 1px ring. A ring reads
// as a border, and the user wants no lines. Light: three soft layers
// (contact, lift, ambient). Dark: depth shadows vanish on dark, so the
// card colour (lighter than the page) lifts it instead: no shadow at all.
export const LIFT =
  "border border-transparent shadow-[0_1px_2px_0_oklch(0_0_0/0.05),0_2px_8px_-2px_oklch(0_0_0/0.08),0_8px_24px_-8px_oklch(0_0_0/0.08)] dark:shadow-none";

// Form fields (inputs, textareas, checkboxes, radios, code boxes) keep a
// faint 1px ring: a field needs a visible boundary to be found.
export const RING =
  "border border-transparent shadow-[0_0_0_1px_oklch(0_0_0/0.08),0_1px_2px_-1px_oklch(0_0_0/0.06),0_2px_4px_0_oklch(0_0_0/0.04)] dark:shadow-[0_0_0_1px_oklch(1_0_0/0.1)]";

export const FLOAT =
  "border border-transparent shadow-[0_2px_4px_-1px_oklch(0_0_0/0.06),0_8px_16px_-4px_oklch(0_0_0/0.1),0_16px_32px_-8px_oklch(0_0_0/0.14)] dark:shadow-[0_12px_24px_-4px_oklch(0_0_0/0.5)]";

export const PHOTO_INSET =
  "pointer-events-none absolute inset-0 rounded-full shadow-[inset_0_0_0_1px_oklch(0_0_0/0.1),inset_0_1px_3px_oklch(0_0_0/0.12)] dark:shadow-[inset_0_0_0_1px_oklch(1_0_0/0.1),inset_0_1px_3px_oklch(0_0_0/0.4)]";

// A list row: its own lifted card on the card colour.
export const CARD = `${LIFT} bg-card rounded-lg`;

// Outline buttons: a small contact shadow, no ring (light); in dark the
// outline variant's own fill (bg-input/30) shapes it. shadcn's outline
// border is cleared in both themes.
export const RING_BUTTON =
  "border border-transparent shadow-[0_1px_2px_0_oklch(0_0_0/0.1),0_1px_3px_0_oklch(0_0_0/0.06)] hover:shadow-[0_1px_2px_0_oklch(0_0_0/0.12),0_2px_6px_-1px_oklch(0_0_0/0.1)] dark:border-transparent dark:shadow-none dark:hover:shadow-none";

"use client";

import { motion, PresenceContext, useReducedMotion } from "motion/react";
import type * as React from "react";
import { useContext, useState } from "react";

/* ─────────────────────────────────────────────────────────
 * MOTION: the block's shared curves and the height reveal.
 *
 *   EASE_OUT        (0.23, 1, 0.32, 1)      answers to a click: icons,
 *                                           fades, label rolls
 *   EASE_IN_OUT     (0.645, 0.045, 0.355, 1) on-screen moves, small heights
 *   EASE_OUT_QUAD   (0.5, 1, 0.89, 1)        tall reveals: speed falls in a
 *                   straight line from 2× average to 0, so it moves from
 *                   the first frame (12% at 16ms over 260ms), never jumps
 *                   more than 12% a frame, and has no creeping tail. One
 *                   continuous motion, never "two steps".
 * ───────────────────────────────────────────────────────── */

export const EASE_OUT = [0.23, 1, 0.32, 1] as const;
export const EASE_IN_OUT = [0.645, 0.045, 0.355, 1] as const;
export const EASE_OUT_QUAD = [0.5, 1, 0.89, 1] as const;

export const wait = (ms: number) =>
  // oxlint-disable-next-line promise/avoid-new
  new Promise<void>((resolve) => {
    setTimeout(resolve, ms);
  });

// Something opening in place: height 0 → auto with a fade. Small rows:
// 210ms open / 150ms close, ease-in-out. Taller content (`tall`, with
// `enter` / `exit` in seconds): EASE_OUT_QUAD for height and fade, the
// fade with no delay (in over the first 60% of the open, out over the
// first half of the close), so the content never squeezes.
// Clipped only while it moves; rows already there on first paint (inside
// AnimatePresence initial={false}) never animate, so they start
// unclipped. Reduced motion: the fade only.
export const Reveal = ({
  children,
  className,
  enter = 0.21,
  exit = 0.15,
  id,
  tall = false,
}: {
  children: React.ReactNode;
  className?: string;
  enter?: number;
  exit?: number;
  /** Id for the moving box, e.g. for a toggle's aria-controls. */
  id?: string;
  tall?: boolean;
}) => {
  const reduce = useReducedMotion();
  const presence = useContext(PresenceContext);
  const animatesIn = presence?.initial !== false;
  const [moving, setMoving] = useState(!reduce && animatesIn);
  const timing = (duration: number, opening: boolean) => {
    const fade = tall ? duration * (opening ? 0.6 : 0.5) : duration;
    return {
      height: { duration, ease: tall ? EASE_OUT_QUAD : EASE_IN_OUT },
      opacity: { duration: fade, ease: tall ? EASE_OUT_QUAD : EASE_OUT },
    };
  };
  return (
    <motion.div
      id={id}
      initial={reduce ? { opacity: 0 } : { height: 0, opacity: 0 }}
      animate={{ height: "auto", opacity: 1, transition: timing(enter, true) }}
      exit={
        reduce
          ? { opacity: 0, transition: { duration: 0.15 } }
          : { height: 0, opacity: 0, transition: timing(exit, false) }
      }
      onAnimationStart={() => setMoving(!reduce)}
      onAnimationComplete={() => setMoving(false)}
      style={{ overflow: moving ? "hidden" : "visible" }}
    >
      <div className={className}>{children}</div>
    </motion.div>
  );
};

"use client";

import {
  CheckmarkCircle02Icon,
  Loading03Icon,
} from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import type { IconSvgElement } from "@hugeicons/react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type * as React from "react";
import { useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { EASE_OUT } from "./motion";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: an async button whose label rolls to its new state.
 *
 *   [ Add passkey ]  click
 *        ↑ label leaves upward (y 0 → -100%, fades)
 *        ↑ the spinner rises in from below (y 100% → 0)
 *   [      ◌      ]  spinner only, centred (busy words: screen readers only)
 *   [   ✓ Added   ]  same roll; back to idle after 1.5s
 *
 * SUFFIX: something shown after the idle words (a ⌘S key hint), sized in
 * with them, so it never changes the button's width either.
 *
 * FIXED WIDTH: the button never changes size. Every state's label is
 * stacked invisibly in one grid cell, so the button is as wide as its
 * longest label from the first paint; the visible label is centred on top.
 *
 * MOTION
 *   label roll    200ms ease-out, out and in together (popLayout, so the
 *                 two labels pass like a conveyor, never stacked)
 *   spinner       600ms a turn (a fast spinner reads as a fast app)
 *   press         0.96 scale, from the shadcn button itself
 *   reduced       labels cross-fade in place; the spinner holds still
 *
 * While busy the button is aria-disabled, not disabled: it keeps full
 * colour (shadcn dims disabled buttons, which would fade the loader) and
 * keeps keyboard focus; clicks are ignored. aria-busy tells screen readers.
 * ───────────────────────────────────────────────────────── */

export type ButtonState = "idle" | "busy" | "done";

const ROLL = { duration: 0.2, ease: EASE_OUT };

const StateIcon = ({
  icon,
  state,
}: {
  icon?: IconSvgElement;
  state: ButtonState;
}) => {
  if (state === "busy") {
    return (
      <HugeiconsIcon
        icon={Loading03Icon}
        strokeWidth={2}
        className="size-4 animate-[spin_600ms_linear_infinite] motion-reduce:animate-none"
      />
    );
  }
  if (state === "done") {
    return (
      <HugeiconsIcon
        icon={CheckmarkCircle02Icon}
        strokeWidth={2}
        className="size-4 text-emerald-600 dark:text-emerald-400"
      />
    );
  }
  return icon ? (
    <HugeiconsIcon icon={icon} strokeWidth={1.75} className="size-4" />
  ) : null;
};

interface Labels {
  idle: string;
  busy?: string;
  done?: string;
}

const STATES: ButtonState[] = ["idle", "busy", "done"];

// The label for a state: the spinner alone while busy (its words go to
// screen readers), otherwise the state's icon and words.
const LabelContent = ({
  icon,
  labels,
  state,
  suffix,
}: {
  icon?: IconSvgElement;
  labels: Labels;
  state: ButtonState;
  suffix?: React.ReactNode;
}) => (
  <>
    <StateIcon icon={icon} state={state} />
    {state === "busy" ? (
      <span className="sr-only">{labels.busy ?? labels.idle}</span>
    ) : (
      (labels[state] ?? labels.idle)
    )}
    {state === "idle" ? suffix : null}
  </>
);

// The rolling label. Keyed by state + text, so any change of words rolls
// (Continue → Verify in a dialog), not only a change of state.
export const RollingLabel = ({
  icon,
  labels,
  reserve = [],
  state,
  suffix,
}: {
  icon?: IconSvgElement;
  labels: Labels;
  /** Other words this button can show (e.g. "Set up" ↔ "Turn off"): room is kept for them too. */
  reserve?: string[];
  state: ButtonState;
  /** Shown after the idle words, e.g. a <Kbd> hint. */
  suffix?: React.ReactNode;
}) => {
  const reduce = useReducedMotion();
  const cell = "col-start-1 row-start-1 flex items-center justify-center";
  return (
    <span className="inline-grid overflow-hidden">
      {/* Sizers: every state, invisible, in the same cell. */}
      {/* Only the states this button uses: a "done" it never shows
          would reserve room for a ✓ it never draws. */}
      {STATES.filter((each) => each === "idle" || labels[each]).map((each) => (
        <span
          key={each}
          aria-hidden
          className={cn(cell, "invisible gap-1.5 whitespace-nowrap")}
        >
          <LabelContent
            icon={icon}
            labels={labels}
            state={each}
            suffix={suffix}
          />
        </span>
      ))}
      {reserve.map((words) => (
        <span
          key={`reserve:${words}`}
          aria-hidden
          className={cn(cell, "invisible gap-1.5 whitespace-nowrap")}
        >
          {words}
        </span>
      ))}
      <span className={cn(cell, "relative")}>
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            key={`${state}:${labels[state] ?? labels.idle}`}
            className="inline-flex items-center gap-1.5 whitespace-nowrap"
            initial={{ opacity: 0, y: reduce ? 0 : "100%" }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: reduce ? 0 : "-100%" }}
            transition={ROLL}
          >
            <LabelContent
              icon={icon}
              labels={labels}
              state={state}
              suffix={suffix}
            />
          </motion.span>
        </AnimatePresence>
      </span>
    </span>
  );
};

type StatusButtonProps = Omit<
  React.ComponentProps<typeof Button>,
  "children"
> & {
  /** Idle, busy (spinner) or done (check). */
  state: ButtonState;
  /** The words for each state; busy and done fall back to idle. */
  labels: Labels;
  /** Icon shown while idle. */
  icon?: IconSvgElement;
  /** Shown after the idle words, e.g. a <Kbd> hint. */
  suffix?: React.ReactNode;
};

export const StatusButton = ({
  className,
  icon,
  labels,
  onClick,
  state,
  suffix,
  ...props
}: StatusButtonProps) => {
  const busy = state === "busy";
  return (
    <Button
      {...props}
      aria-busy={busy || undefined}
      aria-disabled={busy || props["aria-disabled"] || undefined}
      onClick={(event) => {
        if (!busy) {
          onClick?.(event);
        }
      }}
      className={cn(busy && "cursor-progress", className)}
    >
      <RollingLabel icon={icon} state={state} labels={labels} suffix={suffix} />
    </Button>
  );
};

/**
 * Runs an async action as idle → busy → done → idle. Returns the state
 * and `run`, which resolves true on success; on failure it goes straight
 * back to idle and resolves false (show your own error message).
 */
export const useButtonState = (doneFor = 1500) => {
  const [state, setState] = useState<ButtonState>("idle");
  useEffect(() => {
    if (state !== "done") {
      return;
    }
    const timer = setTimeout(() => setState("idle"), doneFor);
    return () => clearTimeout(timer);
  }, [state, doneFor]);

  const run = async (action: () => Promise<unknown>, showDone = true) => {
    setState("busy");
    try {
      await action();
    } catch {
      setState("idle");
      return false;
    }
    setState(showDone ? "done" : "idle");
    return true;
  };

  return [state, run] as const;
};
